begin;
update calendar_private.calendar_days
set challenge = $day22${"type":"matching","visual":"bird-halves","version":"idice-bird-halves-v1","placeholder":false,"title":"Ricomponi gli uccelli della pianura","instructions":"Ogni uccello è diviso in due. Scegli una metà superiore, poi una metà inferiore dal gruppo sotto: le vedrai unite nella stessa figura. Ricomponi tutti e quattro gli uccelli, osservando piume, forma del corpo e coda. Puoi cambiare gli incastri prima di confermare.","sheet":{"image":"images/giochi/uccelli-giorno-22-v2.png","width":1261,"height":1247,"regions":[[0,0,630.5,623.5],[630.5,0,630.5,623.5],[0,623.5,630.5,623.5],[630.5,623.5,630.5,623.5]]},"names":["Fringuello","Cardellino","Picchio muratore","Ballerina bianca"],"scientific_names":["Fringilla coelebs","Carduelis carduelis","Sitta europaea","Motacilla alba"],"solution":[0,1,2,3],"bird_notes":["Il fringuello raffigurato è un maschio: ha il capo grigio-azzurro, il petto rosato e barre bianche sulle ali. Nel puzzle la continuità tra queste barre e le penne scure aiuta a ritrovare la metà giusta. Frequenta boschi, campagne alberate e giardini.","Il cardellino adulto ha una mascherina rossa e una banda gialla sulle ali nere. Il ventre è più chiaro dei fianchi: seguire il passaggio tra questi colori e il disegno delle penne aiuta a ricomporlo. Cerca spesso i semi nelle erbe spontanee.","Il picchio muratore ha un corpo compatto, una coda corta e una striscia nera che attraversa l’occhio. Il dorso grigio-azzurro si distingue dalle parti inferiori più calde. Si muove sui tronchi e può scendere anche a testa in giù.","La ballerina bianca ha un corpo slanciato e una coda lunga, che muove spesso su e giù. Il piumaggio combina bianco, grigio e nero. Nel puzzle sono utili il profilo del corpo, il disegno delle ali e il proseguimento della coda. Si incontra anche lungo rive e corsi d’acqua."],"hint":"Non guardare soltanto il colore: segui il bordo dell’ala, la posizione delle penne, la forma del ventre e il proseguimento della coda.","explanation":"Per ricomporre gli uccelli servono più indizi: il colore del piumaggio, la continuità del disegno sulle ali e le proporzioni del corpo. Una metà può sembrare adatta a prima vista, ma il bordo dell’ala o l’inizio della coda possono suggerire un abbinamento diverso.\n\nSono gli stessi dettagli che aiutano a riconoscere gli uccelli in natura. Qui trovi le figure intere del fringuello, del cardellino, del picchio muratore e della ballerina bianca, con alcuni caratteri da osservare.","sources":[{"title":"Fringuello · LIPU","url":"https://www.lipu.it/uccelli/conoscerli-proteggerli/fringuello"},{"title":"Cardellino · LIPU","url":"https://www.lipu.it/uccelli/conoscerli-proteggerli/cardellino"},{"title":"Picchio muratore · LIPU","url":"https://www.lipu.it/uccelli/conoscerli-proteggerli/picchio-muratore"},{"title":"Ballerina bianca · LIPU","url":"https://www.lipu.it/uccelli/conoscerli-proteggerli/ballerina-bianca"}]}$day22$::jsonb
where day = 22;
